/// Demo screen for multi-format export features.
class ExportSingleExampleHost extends StatefulWidget {
  const ExportSingleExampleHost({
    super.key,
    this.initialTab = 0,
    this.controller,
  });

  final int initialTab;
  final ExportDemoController? controller;

  @override
  State<ExportSingleExampleHost> createState() => _ExportSingleExampleHostState();
}

class _ExportSingleExampleHostState extends State<ExportSingleExampleHost> {
  late final ExportDemoController _controller;
  late final bool _ownsController;
  @override
  void initState() {
    super.initState();
    _ownsController = widget.controller == null;
    _controller = widget.controller ?? ExportDemoController(
      config: geniusPdfConfig,
      documents: demoDocuments,
    );
    _controller.addListener(_onControllerChanged);
    _controller.initialize();
  }

  void _onControllerChanged() {
    if (mounted) setState(() {});
  }

  @override
  void dispose() {
_controller.removeListener(_onControllerChanged);
    if (_ownsController) _controller.dispose();
    super.dispose();
  }


  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final index = widget.initialTab.clamp(0, 2);

    return switch (index) {
        0 => _buildImageExportTab(isDark),
        1 => _buildDocExportTab(isDark),
        2 => _buildBatchExportTab(isDark),
        _ => _buildImageExportTab(isDark),
    };
  }
  Widget _buildImageExportTab(bool isDark) {
    return ComponentPage(
      title: 'Image Export',
      description:
          'Export PDF pages as high-quality PNG or compressed JPEG images.',
      icon: Icons.image_rounded,
