  compress: true,
);
''',
      preview: Column(
        children: [
          Row(
            children: [
              Expanded(
                child: _ExportCard(
                  isDark: isDark,
                  icon: Icons.html_rounded,
                  label: 'HTML',
                  sublabel: 'Web format',
                  gradient: AppColors.purpleGradient,
                  onPressed: _controller.isReady && !_controller.isLoading
                      ? () => _exportTo(GeniusExportFormat.html)
                      : null,
                ),
              ),
