        children: [
          _ExportCard(
            isDark: isDark,
            icon: Icons.dynamic_feed_rounded,
            label: 'Export to All Formats',
            sublabel: 'PNG, HTML, Text',
            gradient: AppColors.primaryGradient,
            onPressed:
                _controller.isReady && !_controller.isLoading ? _batchExport : null,
          ),
          const SizedBox(height: 16),
          _buildStatusAndResult(isDark),
        ],
      ),
    );
  }

  Widget _buildStatusAndResult(bool isDark) {
    return Column(
      children: [
        _buildStatusCard(isDark),
        if (_controller.lastResult != null) ...[
          const SizedBox(height: 16),
          _buildResultCard(isDark),
        ],
      ],
    );
  }
  Widget _buildStatusCard(bool isDark) {
    return FeatureStatusPanel(
      message: _controller.status.isEmpty ? 'Ready for export.' : _controller.status,
      loading: _controller.isLoading,
      tone: _controller.isReady
          ? FeatureExampleTone.success
          : FeatureExampleTone.info,
    );
  }
  Widget _buildResultCard(bool isDark) {
    final result = _controller.lastResult;
    if (result is GeniusExportSuccess) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: <Widget>[
          FeatureStatusPanel(
            message: 'Export completed successfully.',
            tone: FeatureExampleTone.success,
          ),
          const SizedBox(height: 10),
          _buildInfoRow(isDark, 'Format', result.format.displayName),
          _buildInfoRow(isDark, 'Pages', '${result.pageCount}'),
          _buildInfoRow(isDark, 'Size', result.fileSizeFormatted),
          if (_controller.lastFilePath != null)
            _buildInfoRow(isDark, 'Path', _controller.lastFilePath!),
          if (_controller.lastFilePath != null) ...<Widget>[
            const SizedBox(height: 10),
            Align(
              alignment: AlignmentDirectional.centerEnd,
              child: OutlinedButton.icon(
                onPressed: _openLastFile,
                icon: const Icon(Icons.open_in_new_rounded),
                label: const Text('Open exported file'),
              ),
            ),
          ],
        ],
      );
    }
    if (result is GeniusExportFailure) {
      return FeatureStatusPanel(
        message: result.message,
        tone: FeatureExampleTone.danger,
      );
    }
    return const SizedBox.shrink();
  }

  Widget _buildInfoRow(bool isDark, String label, String value) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 4),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          SizedBox(
            width: 60,
            child: Text(
              '$label:',
              style: TextStyle(
                fontWeight: FontWeight.w500,
                color: isDark ? AppColors.darkText : AppColors.lightText,
              ),
            ),
          ),
          Expanded(
            child: Text(
              value,
              style: TextStyle(
                color: isDark
                    ? AppColors.darkTextSecondary
                    : AppColors.lightTextSecondary,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Future<void> _exportTo(GeniusExportFormat format) =>
      _controller.exportTo(format);

  Future<void> _batchExport() => _controller.batchExport();

  Future<void> _openLastFile() async {
    try {
      await _controller.openLastFile();
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Failed to open file: $error'),
          backgroundColor: AppColors.error,
        ),
      );
    }
  }
